let lang="ru";try{lang=localStorage.getItem("foodlab-lang")||"ru"}catch{}let activeCat="all";const $=s=>document.querySelector(s),t=k=>T[lang][k]||k,esc=s=>String(s).replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]));
