function displayMetric(value,digits=1){return Number.isFinite(value)?value.toFixed(digits):"—"}function scaledMetric(value,m,digits=1){return Number.isFinite(value)?(value*m).toFixed(digits):"—"}function list(){let q=$("#search").value.trim().toLocaleLowerCase();return data.filter(f=>(activeCat==="all"||f.cat===activeCat)&&(!q||[f.ru,f.de].some(v=>v.toLocaleLowerCase().includes(q))))}
function render(){let a=list();$("#count").textContent=`${t("countLabel")}: ${a.length} ${t("products")}`;$("#products").innerHTML=a.length?a.map(f=>`<article class="product" tabindex="0" role="button" data-id="${f.id}"><div class="prod-top"><span class="emoji">${f.emoji}</span><span class="tag">${f.external?"OPEN FOOD FACTS":t(catKey[f.cat])}</span></div><h3>${esc(lang==="ru"?f.ru:f.de)}</h3><div class="sub">${f.brand?esc(f.brand)+" · ":""}${esc(lang==="ru"?f.de:f.ru)}</div><p class="desc">${esc(lang==="ru"?f.descRu:f.descDe)}</p><div class="macros"><div class="macro"><strong>${displayMetric(f.p,1)} g</strong><span>${t("protein")}</span></div><div class="macro"><strong>${displayMetric(f.fat,1)} g</strong><span>${t("fat")}</span></div><div class="macro"><strong>${displayMetric(f.carb,1)} g</strong><span>${t("carbs")}</span></div><div class="macro"><strong>${displayMetric(f.cal,0)}</strong><span>kcal</span></div></div><div class="open-label">${t("open")}</div></article>`).join(""):`<div class="info-card">${t("noResults")}</div>`}
function renderSelect(){let s=$("#foodSelect"),old=s.value;s.innerHTML=data.map(f=>`<option value="${f.id}">${esc(lang==="ru"?f.ru:f.de)}</option>`).join("");if(data.some(f=>f.id===old))s.value=old;let ds=$("#drawerFoodSelect"),dold=ds.value;ds.innerHTML=data.map(f=>`<option value="${f.id}">${esc(lang==="ru"?f.ru:f.de)}</option>`).join("");if(data.some(f=>f.id===dold))ds.value=dold;calc();calcDrawer()}
function calc(){let f=data.find(x=>x.id===$("#foodSelect").value)||data[0],g=Math.max(0,Math.min(5000,Number($("#grams").value)||0)),m=g/100;$("#result").innerHTML=`<small>${t("portionResult")} · ${g} g</small><strong>${scaledMetric(f.cal,m,0)} kcal</strong><small>${scaledMetric(f.cal,m*4.184,0)} ${t("kJ")}</small><div class="macros"><div class="macro"><strong>${scaledMetric(f.p,m)} g</strong><span>${t("protein")}</span></div><div class="macro"><strong>${scaledMetric(f.fat,m)} g</strong><span>${t("fat")}</span></div><div class="macro"><strong>${scaledMetric(f.carb,m)} g</strong><span>${t("carbs")}</span></div></div>`}
function openProduct(id){let f=data.find(x=>x.id===id),ru=lang==="ru";if(!f)return;$("#modalContent").innerHTML=`<div class="kicker">${t(catKey[f.cat])}</div><div style="font-size:42px;margin-top:8px">${f.emoji}</div><h2 class="modal-title" id="modalTitle">${esc(ru?f.ru:f.de)}</h2><div class="modal-sub">${esc(ru?f.de:f.ru)}</div><div class="modal-cols"><div><h4>${t("description")}</h4><p>${esc(ru?f.descRu:f.descDe)}</p><h4>${t("allergens")}</h4><p>${esc(ru?f.allRu:f.allDe)}</p><h4>${t("storage")}</h4><p>${esc(ru?f.storeRu:f.storeDe)}</p></div><div><h4>${t("energy")} · 100 g</h4><table class="nutri-table"><tr><td>${t("energy")}</td><td>${displayMetric(f.cal,0)} kcal</td></tr><tr><td>${t("protein")}</td><td>${displayMetric(f.p,1)} g</td></tr><tr><td>${t("fat")}</td><td>${displayMetric(f.fat,1)} g</td></tr><tr><td>${t("carbs")}</td><td>${displayMetric(f.carb,1)} g</td></tr></table><h4 style="margin-top:18px">${t("production")}</h4><p>${esc(ru?f.procRu:f.procDe)}</p></div></div><div class="disclaimer">${esc(t("sourceNote"))}</div>`;$("#modal").classList.add("show");$("#closeModal").focus()}
function categoryCards(){let cats=[["dairy","🥛","catDairy"],["meat","🍗","catMeat"],["fish","🐟","catFish"],["grain","🌾","catGrain"],["fruit","🥦","catFruit"],["legumes","🫘","legumes"],["oils","🫒","oils"],["drinks","🥤","drinks"],["snacks","🍫","snacks"],["prepared","🍱","prepared"],["other","🫒","catOther"]];$("#categoryGrid").innerHTML=cats.map(([c,e,k])=>`<button type="button" class="category" data-jump="${c}"><span class="emoji">${e}</span><strong>${t(k)}</strong><span>${data.filter(f=>f.cat===c).length} ${t("products")}</span></button>`).join("")}
