function offCategory(tags=[]){const x=tags.join(" ").toLowerCase();if(/dairy|milk|cheese|yogurt/.test(x))return "dairy";if(/meat|poultry|chicken|beef|pork/.test(x))return "meat";if(/fish|seafood/.test(x))return "fish";if(/cereal|grain|bread|pasta|rice/.test(x))return "grain";if(/fruit|vegetable/.test(x))return "fruit";if(/beverage|drink|water|juice/.test(x))return "drinks";return "other"}
function offNumber(value){if(value===undefined||value===null||value==="")return null;const n=Number(value);return Number.isFinite(n)&&n>=0?n:null}function normalizeOFF(p){const n=p.nutriments||{},ru=p.product_name_ru||p.product_name||p.product_name_de||"Без названия",de=p.product_name_de||p.product_name||ru;const energyKcal=offNumber(n["energy-kcal_100g"]),energyKj=offNumber(n["energy_100g"]),kcal=energyKcal??(energyKj===null?null:energyKj/4.184),protein=offNumber(n.proteins_100g),fat=offNumber(n.fat_100g),carb=offNumber(n.carbohydrates_100g);return {id:"off-"+(p.code||Math.random().toString(36).slice(2)),cat:offCategory(p.categories_tags||[]),emoji:"📦",ru,de,descRu:(p.ingredients_text||"Сведения об ингредиентах не указаны.").slice(0,260),descDe:(p.ingredients_text_de||p.ingredients_text||"Keine Zutatenangaben verfügbar.").slice(0,260),p:protein,fat,carb,cal:kcal,allRu:p.allergens||"Не указано в базе — проверь упаковку.",allDe:p.allergens||"In der Datenbank nicht angegeben — Verpackung prüfen.",storeRu:"Следуй условиям хранения на упаковке.",storeDe:"Lagerhinweise auf der Verpackung beachten.",procRu:"Данные получены из Open Food Facts. Сведения могут быть неполными.",procDe:"Daten von Open Food Facts; Angaben können unvollständig sein.",brand:p.brands||"",image:p.image_front_small_url||p.image_url||"",barcode:p.code||"",external:true}}
async function searchOpenFoodFacts(){const q=$("#search").value.trim();const status=$("#databaseStatus");if(q.length<2){status.textContent=lang==="ru"?"Введи название продукта (минимум 2 символа).":"Bitte mindestens 2 Zeichen eingeben.";return;}const btn=$("#offSearchBtn");btn.disabled=true;status.textContent=lang==="ru"?"Ищем в Open Food Facts…":"Suche in Open Food Facts…";try{const params=new URLSearchParams({search_terms:q,search_simple:"1",action:"process",json:"1",page_size:"24",page:"1",lc:lang,fields:"code,product_name,product_name_ru,product_name_de,brands,categories_tags,nutriments,ingredients_text,ingredients_text_de,allergens,image_front_small_url,image_url"});const response=await fetch(OFF_BASE+"?"+params.toString(),{headers:{Accept:"application/json"}});if(!response.ok)throw new Error("HTTP "+response.status);const json=await response.json();offProducts=[...new Map((json.products||[]).filter(p=>p.product_name).map(normalizeOFF).map(p=>[p.barcode||`${p.ru.toLocaleLowerCase()}|${p.brand.toLocaleLowerCase()}`,p])).values()];const local=data.filter(x=>!x.external);data.splice(0,data.length,...local,...offProducts);activeCat="all";document.querySelectorAll(".chip").forEach(b=>b.classList.toggle("active",b.dataset.cat==="all"));render();renderSelect();status.textContent=lang==="ru"?`Найдено ${offProducts.length} продуктов из Open Food Facts. Нажми на карточку для подробностей.`:`${offProducts.length} Produkte aus Open Food Facts gefunden. Karte für Details öffnen.`;if(!offProducts.length)status.textContent=lang==="ru"?"Ничего не найдено. Попробуй другое название или немецкое написание.":"Keine Treffer. Anderen oder deutschen Suchbegriff versuchen.";}catch(err){status.textContent=lang==="ru"?"Не удалось подключиться к Open Food Facts. Проверь интернет и попробуй позже.":"Open Food Facts ist nicht erreichbar. Internet prüfen und später erneut versuchen.";console.error("Open Food Facts",err);}finally{btn.disabled=false;}}
