function setLang(n){lang=n;try{localStorage.setItem("foodlab-lang",n)}catch{}document.documentElement.lang=n;document.querySelectorAll("[data-t]").forEach(e=>e.textContent=t(e.dataset.t));document.querySelectorAll("[data-html]").forEach(e=>e.innerHTML=t(e.dataset.html));$("#search").placeholder=t("searchPlaceholder");$("#freeNotes").placeholder=lang==="ru"?$("#freeNotes").dataset.placeholderRu:$("#freeNotes").dataset.placeholderDe;$("#langBtn").textContent=n==="ru"?"DE / RU":"RU / DE";document.title=n==="ru"?"FoodLab — энциклопедия продуктов":"FoodLab — Lebensmittel-Enzyklopädie";document.querySelectorAll(".chip").forEach(b=>b.textContent=t(b.dataset.cat==="all"?"all":b.dataset.cat));render();renderSelect();categoryCards()}
function setCat(c){activeCat=c;document.querySelectorAll(".chip").forEach(b=>b.classList.toggle("active",b.dataset.cat===c));render();$("#catalog").scrollIntoView({behavior:"smooth"})}
$("#langBtn").onclick=()=>setLang(lang==="ru"?"de":"ru");$("#search").oninput=render;$("#filters").onclick=e=>{let b=e.target.closest("[data-cat]");if(b)setCat(b.dataset.cat)};$("#categoryGrid").onclick=e=>{let b=e.target.closest("[data-jump]");if(b)setCat(b.dataset.jump)};$("#reset").onclick=()=>{$("#search").value="";setCat("all")};$("#products").onclick=e=>{let c=e.target.closest("[data-id]");if(c)openProduct(c.dataset.id)};$("#products").onkeydown=e=>{if((e.key==="Enter"||e.key===" ")&&e.target.matches("[data-id]")){e.preventDefault();openProduct(e.target.dataset.id)}};$("#foodSelect").onchange=calc;$("#grams").oninput=calc;$("#closeModal").onclick=()=>$("#modal").classList.remove("show");$("#modal").onclick=e=>{if(e.target===$("#modal"))$("#modal").classList.remove("show")};document.onkeydown=e=>{if(e.key==="Escape")$("#modal").classList.remove("show")};$("#year").textContent=new Date().getFullYear();
const FREE_NOTE_KEY="foodlab-free-notes-v1";
const freeNotes=$("#freeNotes");
function saveFreeNotes(){
 try{localStorage.setItem(FREE_NOTE_KEY,freeNotes.value);$("#noteStatus").textContent=lang==="ru"?"Сохранено на этом устройстве":"Auf diesem Gerät gespeichert"}
 catch{$("#noteStatus").textContent=lang==="ru"?"Не удалось сохранить. Проверь память браузера.":"Speichern fehlgeschlagen. Bitte Browserspeicher prüfen."}
}
try{freeNotes.value=localStorage.getItem(FREE_NOTE_KEY)||""}catch{}
$("#clearFreeNotes").addEventListener("click",()=>{
 if(!freeNotes.value)return;
 if(confirm(lang==="ru"?"Очистить весь текст блокнота?":"Den gesamten Notiztext löschen?")){freeNotes.value="";saveFreeNotes();freeNotes.focus()}
});
freeNotes.addEventListener("input",saveFreeNotes);

const DIARY_KEY="foodlab-nutrition-diary-v1";
const drawer=$("#nutritionDrawer"),backdrop=$("#drawerBackdrop");
function openDrawer(){closeMenu();drawer.classList.add("open");backdrop.classList.add("show");drawer.setAttribute("aria-hidden","false");backdrop.setAttribute("aria-hidden","false");document.body.classList.add("drawer-open");$("#drawerClose").focus()}
function closeDrawer(){drawer.classList.remove("open");backdrop.classList.remove("show");drawer.setAttribute("aria-hidden","true");backdrop.setAttribute("aria-hidden","true");document.body.classList.remove("drawer-open")}
function calcDrawer(){
 const f=data.find(x=>x.id===$("#drawerFoodSelect").value)||data[0],g=Math.max(0,Math.min(5000,Number($("#drawerGrams").value)||0)),m=g/100;
 $("#drawerResult").innerHTML=`<span class="energy">${scaledMetric(f.cal,m,0)} <small>kcal · ${scaledMetric(f.cal,m*4.184,0)} kJ</small></span><div class="drawer-macros"><div><strong>${scaledMetric(f.p,m)} g</strong><span>${t("protein")}</span></div><div><strong>${scaledMetric(f.fat,m)} g</strong><span>${t("fat")}</span></div><div><strong>${scaledMetric(f.carb,m)} g</strong><span>${t("carbs")}</span></div></div>`;
}
function readDiary(){try{return JSON.parse(localStorage.getItem(DIARY_KEY)||"[]")}catch{return []}}
function drawDiary(){
 const entries=readDiary(),box=$("#diaryList"),totals=$("#diaryTotals");
 if(!entries.length){box.innerHTML=`<div class="diary-empty">${t("diaryEmpty")}</div>`;totals.textContent="";return}
 const fields=[["kcal","kcal",0],["p","P",1],["fat","F",1],["carb","C",1]];
 totals.textContent=(lang==="ru"?"Сумма записей: ":"Summe der Einträge: ")+fields.map(([key,label,digits])=>{const values=entries.map(x=>Number.isFinite(x[key])?x[key]:null);const complete=values.every(x=>x!==null);const total=complete?values.reduce((a,b)=>a+b,0):null;return label+" "+displayMetric(total,digits)+(key==="kcal"?" kcal":" g")}).join(" · ");
 box.innerHTML=entries.map(x=>{const safeName=esc(x.name||""),safeDate=esc(x.date||"");return `<div class="diary-item"><div><strong>${safeName} · ${Number(x.grams)||0} g</strong><small>${safeDate}</small></div><b>${displayMetric(Number.isFinite(x.kcal)?x.kcal:null,0)} kcal</b></div>`}).join("");
}
$("#drawerFoodSelect").addEventListener("change",calcDrawer);
$("#drawerGrams").addEventListener("input",calcDrawer);
$("#addDiary").addEventListener("click",()=>{
 const f=data.find(x=>x.id===$("#drawerFoodSelect").value)||data[0],g=Math.max(1,Math.min(5000,Number($("#drawerGrams").value)||0)),m=g/100;
 const entries=readDiary();entries.unshift({name:lang==="ru"?f.ru:f.de,grams:g,kcal:Number.isFinite(f.cal)?Math.round(f.cal*m):null,p:Number.isFinite(f.p)?+(f.p*m).toFixed(1):null,fat:Number.isFinite(f.fat)?+(f.fat*m).toFixed(1):null,carb:Number.isFinite(f.carb)?+(f.carb*m).toFixed(1):null,date:new Date().toLocaleString(lang==="ru"?"ru-RU":"de-DE")});
 try{localStorage.setItem(DIARY_KEY,JSON.stringify(entries.slice(0,100)));drawDiary();$("#addDiary").textContent=t("diarySaved");setTimeout(()=>$("#addDiary").textContent=t("addDiary"),1400)}catch{alert(lang==="ru"?"Не удалось сохранить дневник в браузере.":"Das Tagebuch konnte im Browser nicht gespeichert werden.")}
});
$("#clearDiary").addEventListener("click",()=>{if(readDiary().length&&confirm(t("diaryConfirm"))){localStorage.removeItem(DIARY_KEY);drawDiary()}});
drawDiary();
setLang(lang);



